const fs = require('node:fs')
const fsp = fs.promises
const { join } = require('node:path')
const { tmpdir } = require('node:os')
const d = await fsp.mkdtemp(join(tmpdir(), 'mirage-host-'))
await fsp.writeFile(join(d, 'h.txt'), 'from the host')
await fsp.copyFile(join(d, 'h.txt'), '/data/in.txt')
await fsp.copyFile('/data/in.txt', join(d, 'out.txt'))
console.log(await fsp.readFile(join(d, 'out.txt'), 'utf8'))
console.log((await fsp.readdir(d)).sort().join(' '))
try {
  await fsp.rename('/data/in.txt', join(d, 'moved.txt'))
} catch (e) {
  console.log(e.code)
}
await fsp.rm(d, { recursive: true })
console.log(fs.existsSync(d) ? 'there' : 'gone')

