import errno, os, shutil
calls = [(os.rmdir, '/data/d/m'), (shutil.rmtree, '/data/d/m'), (shutil.rmtree, '/data/d'), (os.rmdir, '/data')]
for call, path in calls:
    try:
        call(path)
        print('removed')
    except OSError as e:
        print(errno.errorcode[e.errno])

