const fsp = require('node:fs').promises
const calls = [
  () => fsp.rmdir('/data/d/m'),
  () => fsp.rm('/data/d/m', { recursive: true }),
  () => fsp.rm('/data/d', { recursive: true }),
  () => fsp.rmdir('/data'),
]
for (const call of calls) {
  try {
    await call()
    console.log('removed')
  } catch (e) {
    console.log(e.code)
  }
}

const fs = require('node:fs')
const { tmpdir } = require('node:os')
const calls = [
  () => fs.readFileSync('/data/f.txt'),
  () => fs.statSync('/data/f.txt'),
  () => fs.existsSync('/data/f.txt'),
  () => fs.watch('/data/f.txt', () => undefined),
]
for (const call of calls) {
  try {
    call()
    console.log('served')
  } catch (e) {
    console.log(e.code)
  }
}
try {
  for await (const _ of fs.promises.watch('/data/f.txt')) break
} catch (e) {
  console.log(e.code)
}
console.log(fs.existsSync(tmpdir()) ? 'host' : 'none')
